"use client";

import React, { useEffect, useState } from "react";
import { useSocket } from "@/contexts/SocketContext";
import { useRouter } from "next/navigation";

export default function CallModal() {
  const socket = useSocket();
  const router = useRouter();
  const [incoming, setIncoming] = useState(null);

  useEffect(() => {
    if (!socket) return;
    const onCall = (data) => setIncoming(data);
    socket.on("incoming_call", onCall);
    return () => socket.off("incoming_call", onCall);
  }, [socket]);

  if (!socket || !incoming) return null;
  const { from, offer, isVoice } = incoming;

  const accept = () => {
    const qp = new URLSearchParams({
      from,
      offer: JSON.stringify(offer),
      isVoice: isVoice ? "1" : "0",
    }).toString();
    router.push(`/call?${qp}`);
    setIncoming(null);
  };
  const reject = () => {
    socket.emit("end_call", { to: from });
    setIncoming(null);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white p-6 rounded shadow-lg text-center">
        <h2 className="text-xl font-bold mb-4">
          {isVoice ? "Voice" : "Video"} call from {from}
        </h2>
        <div className="flex justify-center gap-4">
          <button
            onClick={accept}
            className="px-4 py-2 bg-green-600 text-white rounded"
          >
            Accept
          </button>
          <button
            onClick={reject}
            className="px-4 py-2 bg-red-600 text-white rounded"
          >
            Reject
          </button>
        </div>
      </div>
    </div>
  );
}
